export function normalizeWord(word) {
  if (!word) return '';
  return word
    .toString()
    .trim()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toUpperCase();
}

export function isValidWord(word) {
  const normalized = normalizeWord(word);
  if (normalized.length !== 5) return false;
  if (!/^[A-Z]{5}$/.test(normalized)) return false;

  // 1. Está no dicionário exato de 7.479 palavras em português
  if (ALL_PORTUGUESE_WORDS.has(normalized)) return true;

  // 2. Está na lista de palavras secretas
  if (SECRET_WORDS.includes(normalized)) return true;

  // 3. Tolerância para gírias/flexões com vogais (nunca trava o jogador injustamente)
  if (/[AEIOUY]/.test(normalized)) {
    return true;
  }

  return false;
}

export function pickFourRandomWords() {
  const chosen = [];
  while (chosen.length < 4) {
    const idx = Math.floor(Math.random() * SECRET_WORDS.length);
    const word = SECRET_WORDS[idx];
    if (!chosen.includes(word)) {
      chosen.push(word);
    }
  }
  return chosen;
}
